using System.Text.Json;
using System.Text.Json.Serialization;

namespace SoftThorn.MAL.ApiClient
{
    // Hooks into the generated clients (see AutoGeneratedClient.cs).
    // MAL returns some numbers as strings, although the spec declares them as integers (e.g. statistics.status.watching on anime details).
    internal static class MalJsonSerializerSettings
    {
        public static void Update(JsonSerializerOptions settings)
        {
            settings.NumberHandling |= JsonNumberHandling.AllowReadingFromString;
        }
    }

    partial class CatalogClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MalJsonSerializerSettings.Update(settings);
    }

    partial class AnimeClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MalJsonSerializerSettings.Update(settings);
    }

    partial class ForumClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MalJsonSerializerSettings.Update(settings);
    }

    partial class MangaClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MalJsonSerializerSettings.Update(settings);
    }

    partial class UsersClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MalJsonSerializerSettings.Update(settings);
    }
}
